def minPath(grid, k):
    """Construct the lexicographically smallest path, allowing revisited cells."""
    size = len(grid)
    row, column = next(
        (row_index, column_index)
        for row_index, values in enumerate(grid)
        for column_index, value in enumerate(values)
        if value == 1
    )
    smallest_neighbor = min(
        grid[row + row_offset][column + column_offset]
        for row_offset, column_offset in ((-1, 0), (1, 0), (0, -1), (0, 1))
        if 0 <= row + row_offset < size and 0 <= column + column_offset < size
    )
    # Returning to 1 after its least neighbor minimizes every subsequent prefix.
    path = []
    for position in range(k):
        path.append(1 if position % 2 == 0 else smallest_neighbor)
    return path

