def _maximum_depth(group: str) -> int:
    """Track the greatest running balance of a single literal-space token."""
    balance = 0
    deepest = 0
    for character in group:
        if character == "(":
            balance += 1
        elif character == ")":
            balance -= 1
        deepest = max(deepest, balance)
    return deepest


